const COPY_FIELDS = ["title", "subtitle", "overview", "challenge", "solution", "status", "type"];
const read = (file) => fs.readFileSync(path.join(ROOT, file), "utf8");
const eol = (text) => (text.includes("\r\n") ? "\r\n" : "\n");
const serialise = (data, original) => `${JSON.stringify(data, null, 2).replaceAll("\n", eol(original))}${original.endsWith("\n") ? eol(original) : ""}`;

function apply() {
  const detailsFile = "data/portfolio/project-details.json";
  const detailsText = read(detailsFile);
  const details = JSON.parse(detailsText);
  const packs = Object.fromEntries(["de", "es", "fr"].map((locale) => {
    const file = `data/i18n/packs/${locale}/projects.json`;
    const text = read(file);
    return [locale, { file, text, data: JSON.parse(text) }];
  }));
  for (const [slug, row] of Object.entries(CORRECTIONS)) {
    const record = details[slug];
    if (!record) throw new Error(`project-details.json has no ${slug}`);
    for (const field of COPY_FIELDS) {
      if (!row[field]) continue;
      record[field] = { en: row[field][0], tr: row[field][1] };
      for (const [index, locale] of [[2, "de"], [3, "es"], [4, "fr"]]) packs[locale].data[slug][field] = row[field][index];
    }
    if (row.features) {
      record.features = { en: row.features.map((item) => item[0]), tr: row.features.map((item) => item[1]) };
      for (const [index, locale] of [[2, "de"], [3, "es"], [4, "fr"]]) packs[locale].data[slug].features = row.features.map((item) => item[index]);
    }
    if (row.links) {
      record.links = row.links.map((link) => ({ label: { en: link.label[0], tr: link.label[1] }, url: link.url }));
      for (const [index, locale] of [[2, "de"], [3, "es"], [4, "fr"]]) {
        if (row.links.length) packs[locale].data[slug].links = row.links.map((link) => ({ label: link.label[index] }));
        else delete packs[locale].data[slug].links;
      }
    }
    if (row.stack) record.stack = row.stack;
    if (row.year) record.year = row.year;
  }
  return [[detailsFile, detailsText, serialise(details, detailsText)], ...Object.values(packs).map((pack) => [pack.file, pack.text, serialise(pack.data, pack.text)])];
}

const check = process.argv.includes("--check");
const invoked = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invoked) {
  const drift = [];
  for (const [file, before, after] of apply()) {
    if (before === after) continue;
    if (check) drift.push(file);
    else fs.writeFileSync(path.join(ROOT, file), after);
  }
  if (check && drift.length) {
    console.error(`Project records drifted from the audited table: ${drift.join(", ")}`);
    process.exit(1);
  }
  console.log(check ? `Project records match the audited table (${Object.keys(CORRECTIONS).length} rows, ${LOCALES.length} locales).` : `Applied ${Object.keys(CORRECTIONS).length} audited project corrections.`);
}
